function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<integer>;
  var currentGroup := new List<string>;
  var groups := new List<string>;
  var ignoreSpace := True;
  var i := 1;
  while i <= parenString.Length do
  begin
    var ch := parenString[i];
    if ch = ' ' then
    begin
      ignoreSpace := True;
      continue;
    end;
    if ch = '(' then
    begin
      if ignoreSpace then
      begin
        currentGroup.Add('(');
        stack.Push(currentGroup.Count - 1);
        currentGroup.Clear;
        ignoreSpace := False;
      end
      else
      begin
        currentGroup.Add('(');
        stack.Push(currentGroup.Count - 1);
      end;
    end
    else if ch = ')' then
    begin
      if stack.Count = 0 then
        break;
      currentGroup.Add(')');
      var start := stack.Pop;
      if stack.Count = 0 then
      begin
        groups.Add(string.Join('', currentGroup));
        currentGroup.Clear;
        ignoreSpace := True;
      end
      else
      begin
        currentGroup[start] := string.Join('', currentGroup);
        ignoreSpace := True;
      end;
    end;
    i += 1;
  end;
  Result := groups.ToArray;
end;


