function ParseNestedParens(parenString: string): array of integer;
begin
  var stack := new Stack<integer>;
  var level := 0;
  var indices := new List<integer>;
  var start := 1;
  for var i := 1 to parenString.Length do
  begin
    if parenString[i] = '(' then
    begin
      if stack.Count = 0 then
        start := i;
      stack.Push(level);
      level += 1;
    end
    else if parenString[i] = ')' then
    begin
      level -= 1;
      if stack.Count = 0 then
        indices.Add(i - start)
      else
      begin
        stack.Pop;
        if stack.Count = 0 then
          indices.Add(i - start);
      end;
    end;
  end;
  Result := indices.ToArray;
end;

