function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  if n <= 1 then
  begin
    Result := str;
    exit;
  end;

  var dp := new integer[n, n];
  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 1;
    for var j := i + 1 to n - 1 do
    begin
      if str[i + 1] = str[j + 1] then
        dp[i, j] := dp[i + 1, j - 1] + 2
      else
        dp[i, j] := Max(dp[i + 1, j], dp[i, j - 1]);
    end;
  end;

  var res := new StringBuilder;
  var i := 1;
  var j := n;
  while (i <= j) and (dp[i - 1, n - 1] <> 0) do
  begin
    if str[i] = str[j] then
    begin
      i += 1;
      j -= 1;
      res.Append(str[i]);
    end
    else
    begin
      j -= 1;
      res.Append(str[j + 1]);
    end;
  end;

  Result := res.ToString;
end;

begin
end.




