function Factorize(n: integer): array of integer;
begin
  var factors := new List<integer>;
  var num := n;
  var i := 2;
  while i * i <= num do
  begin
    while num mod i = 0 do
    begin
      if not factors.Contains(i) then
        factors.Add(i);
      num := num div i;
    end;
    i += 1;
  end;
  if num > 1 then
  begin
    if not factors.Contains(num) then
      factors.Add(num);
  end;
  Result := factors.ToArray;
end;


