function TriplesSumToZero(l: array of integer): boolean;
begin
  var sorted := l.ToArray;
  sorted.Sort;
  for var i := 0 to sorted.Length - 3 do
  begin
    if (i > 0) and (sorted[i] = sorted[i - 1]) then
      continue;
    var left := i + 1;
    var right := sorted.Length - 1;
    while left < right do
    begin
      var total := sorted[i] + sorted[left] + sorted[right];
      if total = 0 then
      begin
        Result := True;
        exit;
      end
      else if total < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;
  Result := False;
end;

