  var dp := new integer[n, n];
  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 0;
    for var j := i + 1 to n - 1 do
    begin
      if arr[i] = arr[j] then
        dp[i, j] := dp[i + 1, j - 1]
      else
        dp[i, j] := Min(dp[i + 1, j], dp[i, j - 1]) + 1;
    end;
  end;
  Result := dp[0, n - 1];
end;


