function DecimalToBinary(decimal: integer): string;
begin
  if decimal = 0 then
  begin
    Result := '0';
    exit;
  end;

  var binary := '';
  while decimal > 0 do
  begin
    var remainder := decimal mod 2;
    binary := remainder.ToString + binary;
    decimal := decimal div 2;
  end;

  Result := 'db' + binary + 'db';
end;


