    var isPalindrome := True;

    for var j := 1 to numStr.Length div 2 do
    begin
      if numStr[j] <> numStr[numStr.Length - j + 1] then
      begin
        isPalindrome := False;
        break;
      end;
    end;

    if isPalindrome then
    begin
      if i mod 2 = 0 then
        evenCount += 1
      else
        oddCount += 1;
    end;
  end;

  Result := (evenCount, oddCount);
end;

