function Exchange(lst1, lst2: array of integer): string;
begin
  var oddCount1 := 0;
  var oddCount2 := 0;
  var evenCount1 := 0;
  var evenCount2 := 0;

  foreach var num in lst1 do
    if num mod 2 <> 0 then
      oddCount1 += 1
    else
      evenCount1 += 1;

  foreach var num in lst2 do
    if num mod 2 <> 0 then
      oddCount2 += 1
    else
      evenCount2 += 1;

  if (oddCount1 + evenCount2) mod 2 <> 0 then
    Result := 'NO'
  else
  begin
    var need := (oddCount1 - evenCount2) div 2;
    if need > 0 then
      Result := 'YES'
    else
      Result := 'NO';
  end;
end;
