function Minsubarraysum(nums: array of integer): integer;
begin
  var minSum := integer.MaxValue;
  var currentSum := 0;
  var left := 0;

  for var right := 0 to nums.Length - 1 do
  begin
    currentSum += nums[right];
    while currentSum >= minSum do
    begin
      minSum := currentSum;
      currentSum -= nums[left];
      left += 1;
    end;
  end;

  if minSum <> integer.MaxValue then
    Result := minSum
  else
    Result := 0;
end;


function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var buckets := new integer[m, n];
  var count := 0;

  // Count the number of water in each well
  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
        buckets[i, j] := 1;

  // Sort the wells by their water content
  var sorted := new (integer, integer, integer)[m * n];
  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      sorted[count] := (buckets[i, j], i, j);
  &Array.Sort(sorted, (x, y) -> x[0].CompareTo(y[0]));

  // Distribute water to wells
  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      var (bucket, x, y) := sorted[i * n + j];
      if (bucket = 1) and (grid[x][y] = 1) then
      begin
        grid[x][y] := 0;
        count += 1;
        if (x > 0) and (grid[x - 1][y] = 0) then
        begin
          buckets[x - 1, y] := 1;
          count -= 1;
        end;
        if (y > 0) and (grid[x][y - 1] = 0) then
        begin
          buckets[x, y - 1] := 1;
          count -= 1;
        end;
      end;
    end;

  Result := count;
end;

begin
end.




