function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new List<(integer, integer)>;
  directions.Add((0, 1));
  directions.Add((1, 0));
  directions.Add((0, -1));
  directions.Add((-1, 0));

  var visited := new HashSet<(integer, integer, integer)>;
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((0, 0, 0));
  var ans := new List<integer>;

  while queue.Count > 0 do
  begin
    var (x, y, steps) := queue.Dequeue;
    ans.Add(grid[x, y]);

    for var d := 0 to directions.Count - 1 do
    begin
      var (dx, dy) := directions[d];
      var nx := x + dx;
      var ny := y + dy;

      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and 
         not visited.Contains((nx, ny, steps + 1)) then
      begin
        queue.Enqueue((nx, ny, steps + 1));
        visited.Add((nx, ny, steps + 1));
      end;
    end;
  end;

  ans.Sort;
  Result := ans.ToArray;
end;

begin
end.




function Tri(n: integer): array of real;
begin
  var trib := new real[n + 1];
  trib[0] := 3;
  trib[1] := 1;
  trib[2] := 2;

  for var i := 3 to n do
  begin
    if i mod 2 = 0 then
      trib[i] := trib[i - 1] + trib[i - 2] + trib[i]
    else
      trib[i] := trib[i - 1] + trib[i - 2] + trib[i - 1];
  end;

  var res := new real[n + 1];
  for var i := 0 to n do
    res[i] := trib[i];

  Result := res;
end;


