function CanArrange(arr: array of integer): integer;
begin
  var count := new Dictionary<integer, integer>;
  var maxVal := 0;
  var minVal := 0;

  foreach var num in arr do
  begin
    if not count.ContainsKey(num) then
      count[num] := 0;
    count[num] += 1;
    maxVal := Max(maxVal, num);
  end;

  while minVal <= maxVal do
  begin
    if not count.ContainsKey(minVal) then
    begin
      Result := -1;
      exit;
    end;

    if count[minVal] > 0 then
    begin
      count[minVal] -= 1;
      if minVal <> maxVal then
        maxVal -= 1;
