function RightAngleTriangle(a, b, c: integer): boolean;
begin
  if (a * a + b * b = c * c) or (a * a + c * c = b * b) or (b * b + c * c = a * a) then
    Result := True
  else
    Result := False;
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';

  foreach var word in words do
  begin
    var uniqueChars := new HashSet<char>(word.ToLower);
    var count := uniqueChars.Count;
    if count > maxUnique then
    begin
      maxUnique := count;
      maxWord := word;
    end;
  end;

  Result := maxWord;
end;

begin
end.




function Eat(number, need, remaining: integer): (integer, integer);
begin
  if remaining >= need then
  begin
    Result := (number + need, remaining - need);
  end
  else
  begin
    Result := (number + remaining, 0);
  end;
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 1 to operand.Length - 1 do
  begin
    case op[i-1] of
      '+': res += operand[i];
      '-': res -= operand[i];
      '*': res *= operand[i];
      '//': res := res div operand[i];
      '**': res := res * operand[i];
    end;
  end;
  Result := res;
end;

begin
end.




function Solve(s: string): string;
begin
  var letters := new List<char>;
  var nonLetters := new List<char>;

  for var i := 1 to s.Length do
  begin
    var c := s[i];
    if Char.IsLetter(c) then
      letters.Add(c)
    else
      nonLetters.Add(c);
  end;

  letters.Reverse;
  nonLetters.Reverse;

  var res := new List<char>;
  var i := 1;
  var j := 1;

  while (i <= letters.Count) and (j <= nonLetters.Count) do
  begin
    if Char.IsLetter(letters[i]) then
    begin
      res.Add(letters[i]);
      i += 1;
    end
    else
    begin
      res.Add(nonLetters[j]);
      j += 1;
    end;
  end;

  while i <= letters.Count do
  begin
    res.Add(letters[i]);
    i += 1;
  end;

  while j <= nonLetters.Count do
  begin
    res.Add(nonLetters[j]);
    j += 1;
  end;

  Result := new string(res.ToArray);
end;

begin
end.




function StringToMd5(text: string): string;
begin
  if string.IsNullOrEmpty(text) then
  begin
    Result := nil;
    exit;
  end;

  var bytes := Encoding.UTF8.GetBytes(text);
  var hasher := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var hash := hasher.ComputeHash(bytes);
  var sb := new System.Text.StringBuilder;

  foreach var b in hash do
    sb.Append(b.ToString('x2'));

  Result := sb.ToString;
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b step 2 do
    res.Add(i);
  Result := res.ToArray;
end;
